import pandas as pd, numpy as np
base='/app/dataset'
st=pd.read_csv(base+'/stations.csv')
rd=pd.read_csv(base+'/readings.csv',parse_dates=['timestamp'])
meta=st.set_index('station_id')
def dist(lat1,lon1,lat2,lon2):
 R=6371; lat1=np.radians(lat1); lon1=np.radians(lon1); lat2=np.radians(lat2); lon2=np.radians(lon2)
 return R*np.sqrt(((lon2-lon1)*np.cos((lat1+lat2)/2))**2+(lat2-lat1)**2)

def lag_scores(peer='nearest', k=8, interp=True):
 rows=[]
 for pol,sub in rd.groupby('pollutant'):
  piv=sub.pivot(index='timestamp',columns='station_id',values='current_reading').sort_index()
  vals=piv.interpolate(method='time',limit_direction='both') if interp else piv
  ids=list(piv.columns)
  coords=meta.loc[ids,['latitude','longitude']].values
  D=np.zeros((len(ids),len(ids)))
  for i in range(len(ids)): D[i]=dist(coords[i,0],coords[i,1],coords[:,0],coords[:,1])
  for i,sid in enumerate(ids):
   if peer=='same_district':
    peers=[j for j in ids if j!=sid and meta.loc[j,'district']==meta.loc[sid,'district']]
   else:
    peers=[ids[j] for j in np.argsort(D[i]) if ids[j]!=sid][:k]
   if len(peers)<2: continue
   series=vals[peers].median(axis=1)
   x=vals[sid]
   corr0=x.corr(series)
   best_lag=0; best_corr=-999
   for lag in range(-5,6):
    if lag==0: continue
    c=x.corr(series.shift(lag))
    if pd.notna(c) and c>best_corr:
     best_corr=c; best_lag=lag
   rows.append((sid,pol,meta.loc[sid,'district'],corr0,best_lag,best_corr,best_corr-corr0,piv[sid].isna().sum(),x.mean(),x.std(),len(peers)))
 return pd.DataFrame(rows,columns='station_id pollutant district corr0 best_lag best_corr gain missing mean std npeers'.split())
for params in [('nearest',8,True),('nearest',5,True),('same_district',8,True),('nearest',8,False),('same_district',8,False)]:
 df=lag_scores(*params)
 print('\nLag params',params)
 print(df.sort_values('gain',ascending=False).head(15).to_string(index=False,float_format=lambda v:f'{v:.3f}'))
